private fun JsonObject.requireStringArgument(name: String): String = this[name]?.jsonPrimitive?.content
    ?: mcpFail("Missing required argument `$name`")

private fun JsonObject.requireIntArgument(name: String): Int = this[name]?.jsonPrimitive?.int
    ?: mcpFail("Missing required argument `$name`")

private fun JsonObject.optionalStringArgument(name: String): String? = this[name]?.jsonPrimitive?.content

private fun JsonObject.optionalIntArgument(name: String): Int? = this[name]?.jsonPrimitive?.intOrNull

private fun JsonObject.optionalBooleanArgument(name: String): Boolean? = this[name]?.jsonPrimitive?.booleanOrNull

private fun JsonObject.requireStringListArgument(name: String): List<String> = this[name]?.jsonArray?.map { it.jsonPrimitive.content }
    ?: mcpFail("Missing required argument `$name`")

private fun JsonObject.optionalStringListArgument(name: String): List<String>? = this[name]?.jsonArray?.map { it.jsonPrimitive.content }

private fun JsonObject.requireIntListArgument(name: String): List<Int> = this[name]?.jsonArray?.map { it.jsonPrimitive.int }
    ?: mcpFail("Missing required argument `$name`")

private fun JsonObject.optionalIntListArgument(name: String): List<Int>? = this[name]?.jsonArray?.map { it.jsonPrimitive.int }

private fun JsonObject.requireWasmFrameListArgument(name: String): List<WasmFrameInput> {
  val array = this[name]?.jsonArray ?: mcpFail("Missing required argument `$name`")
  return array.mapIndexed { index, element ->
      val value = element.jsonObject
      WasmFrameInput(
          funcidx = value["funcidx"]?.jsonPrimitive?.int
              ?: mcpFail("Invalid `$name[$index].funcidx`: expected integer"),
          codeOffset = value["codeOffset"]?.jsonPrimitive?.longOrNull,
          module = value["module"]?.jsonPrimitive?.content,
          label = value["label"]?.jsonPrimitive?.content,
      )
  }
}

private fun JsonObject.optionalWasmFrameListArgument(name: String): List<WasmFrameInput>? {
  val array = this[name]?.jsonArray ?: return null
  return array.mapIndexed { index, element ->
      val value = element.jsonObject
      WasmFrameInput(
          funcidx = value["funcidx"]?.jsonPrimitive?.int
              ?: mcpFail("Invalid `$name[$index].funcidx`: expected integer"),
          codeOffset = value["codeOffset"]?.jsonPrimitive?.longOrNull,
          module = value["module"]?.jsonPrimitive?.content,
          label = value["label"]?.jsonPrimitive?.content,
      )
  }
}

private fun JsonObject.requireSourceLocationListArgument(name: String): List<SourceLocationInput> {
  val array = this[name]?.jsonArray ?: mcpFail("Missing required argument `$name`")
  return array.map { element ->
      val value = element.jsonObject
      SourceLocationInput(
          funcidx = value["funcidx"]?.jsonPrimitive?.intOrNull,
          codeOffset = value["codeOffset"]?.jsonPrimitive?.longOrNull,
      )
  }
}

private fun JsonObject.requireIntMapArgument(name: String): Map<String, Int> {
  val element = this[name] ?: mcpFail("Missing required argument `$name`")
  val value = element as? JsonObject
      ?: mcpFail("Invalid `$name`: expected object { from: int, to: int }")
  return value.mapValues { (key, field) ->
      (field as? JsonPrimitive)?.takeUnless { it.isString }?.intOrNull
          ?: mcpFail("Invalid `$name.$key`: expected integer")
  }
}

/**
 * Looks up `McpToolCategory` reflectively. The class was added in IntelliJ
 * 2026.1 and is absent on 2025.2 / 2025.3, so we return `null` there and the
 * descriptor builder picks a category-less constructor.
 */
private fun hexanaToolCategory(): Any? {
  val categoryClass = try {
      Class.forName("com.intellij.mcpserver.McpToolCategory")
  } catch (_: ClassNotFoundException) {
      return null
  }
  val constructors = categoryClass.constructors
  val fourArgumentConstructor = constructors.firstOrNull { it.parameterCount == 4 }
  if (fourArgumentConstructor != null) {
      return fourArgumentConstructor.newInstance(
          "HexanaToolset",
          "org.jetbrains.hexana.mcp.HexanaToolset",
          false,
          true,
      )
  }
  return constructors.single { it.parameterCount == 2 }.newInstance(
      "HexanaToolset",
      "org.jetbrains.hexana.mcp.HexanaToolset",
  )
}

/**
 * Builds a `McpToolDescriptor` against whichever constructor shape the host
 * platform exposes:
 *   * 2025.2 / 2025.3 (no `McpToolCategory`): `(name, description, inputSchema, outputSchema)`
 *   * 2026.1+ (with `McpToolCategory`): 6-arg or 8-arg shapes with `category`.
 */
private fun hexanaToolDescriptor(
  name: String,
  description: String,
  fullyQualifiedName: String,
  inputSchema: McpToolSchema,
  outputSchema: McpToolSchema,
): McpToolDescriptor {
  val category = hexanaToolCategory()
  val constructors = McpToolDescriptor::class.java.constructors
  if (category != null) {
      val categoryClass = category::class.java
      constructors.firstOrNull {
          it.parameterTypes.contentEquals(
              arrayOf(
                  String::class.java,
                  String::class.java,
                  categoryClass,
                  String::class.java,
                  inputSchema::class.java,
                  outputSchema::class.java,
              )
          )
      }?.let {
          return it.newInstance(
              name,
              description,
              category,
              fullyQualifiedName,
              inputSchema,
              outputSchema,
          ) as McpToolDescriptor
      }
      constructors.firstOrNull {
          it.parameterCount == 8 && it.parameterTypes.getOrNull(3) == categoryClass
      }?.let {
          return it.newInstance(
              name,
              null,
              description,
              category,
              fullyQualifiedName,
              inputSchema,
              outputSchema,
              null,
          ) as McpToolDescriptor
      }
      constructors.firstOrNull {
          it.parameterCount == 8 && it.parameterTypes.getOrNull(4) == categoryClass
      }?.let {
          return it.newInstance(
              name,
              null,
              description,
              fullyQualifiedName,
              category,
              inputSchema,
              outputSchema,
              null,
          ) as McpToolDescriptor
      }
      constructors.firstOrNull { it.parameterCount == 6 }?.let {
          return it.newInstance(
              name,
              description,
              category,
              fullyQualifiedName,
              inputSchema,
              outputSchema,
          ) as McpToolDescriptor
      }
  }
  constructors.firstOrNull {
      it.parameterCount == 4 &&
          it.parameterTypes[0] == String::class.java &&
          it.parameterTypes[1] == String::class.java &&
          it.parameterTypes[2] == inputSchema::class.java &&
          it.parameterTypes[3] == outputSchema::class.java
  }?.let {
      return it.newInstance(
          name,
          description,
          inputSchema,
          outputSchema,
      ) as McpToolDescriptor
  }
  error(
      "No supported McpToolDescriptor constructor found. Available shapes: " +
          constructors.joinToString { ctor -> ctor.parameterTypes.joinToString(prefix = "(", postfix = ")") { it.simpleName } }
  )
}
